    "organizingIdeaDescription": "Exploring the dynamic relationships between people, place, and time supports understanding of perspectives and events to make meaning of the world.",
    "guidingQuestion": "How does the land in Canada differ from place to place?",
    "learningOutcome": "Students examine major physical regions of Canada.",
    "type": "Knowledge",
    "text": "Maps and globes can represent the location of places, including\n• physical regions\n• major cities\n• provinces and territories Canada has distinct physical regions, for example,\n• Canadian Shield\n• Great Lakes\n• Prairies\n• Arctic\n• Appalachian Mountains Physical features are landforms and bodies of water.",
