    "organizingIdeaDescription": "Evaluating processes and structures of organizations builds understanding of decision making in the world.",
    "guidingQuestion": "How is the government of Canada organized?",
    "learningOutcome": "Students investigate historical influences on the federal government in Canada.",
    "type": "Knowledge",
    "text": "The Fathers of Confederation, including Anglophone and Francophone politicians, contributed to the negotiation of the British North America Act (1867), which is also known as the BNA Act or the Constitution Act of 1867.",
    "curriculumFormat": "k6-standard",
    "bloomEligible": false,
