    "organizingIdea": "Systems",
    "organizingIdeaDescription": "Evaluating processes and structures of organizations builds understanding of decision making in the world.",
    "guidingQuestion": "How did economic opportunities influence the establishment of Canada?",
    "learningOutcome": "Students examine the role of the fur trade in the development of Canada.",
    "type": "Understanding",
    "text": "Trade can contribute to social and economic change. Model the fur trade’s system of exchange.",
    "curriculumFormat": "k6-standard",
    "bloomEligible": false,
    "assessmentTarget": false,
    "sourcePage": 6,
    "source": "Alberta Social Studies (K–6) Curriculum, May 2025",
