    "organizingIdea": "Time and Place",
    "organizingIdeaDescription": "Exploring the dynamic relationships between people, place, and time supports understanding of perspectives and events to make meaning of the world.",
    "guidingQuestion": "How can history provide insight into modern democracies?",
    "learningOutcome": "Students relate the foundational principles of democracy to government systems throughout time and place.",
    "type": "Knowledge",
    "text": "Male patricians and plebians could vote for a representative (magistrate) to the senate and assemblies.",
    "curriculumFormat": "k6-standard",
    "bloomEligible": false,
    "assessmentTarget": false,
    "sourcePage": 2,
