    "guidingQuestion": "How can history provide insight into modern democracies?",
    "learningOutcome": "Students relate the foundational principles of democracy to government systems throughout time and place.",
    "type": "Knowledge",
    "text": "The Roman Republic was composed of three branches of government based on the Constitution:\n• executive: two consuls\n• legislative: senate and assemblies (comitia centuriata, comitia tributa, comitia curiata, concilium plebis)\n• judicial: judges Athenian direct democracy and Roman representative democracy were limited by lack of efficiency and representation.",
    "curriculumFormat": "k6-standard",
    "bloomEligible": false,
    "assessmentTarget": false,
