    "grade": "Grade 7",
    "subject": "Social Studies",
    "organizingIdea": "Time and Place",
    "organizingIdeaDescription": "Exploring the dynamic relationships between people, place, and time supports understanding of perspectives and events to make meaning of the world.",
    "guidingQuestion": "How was the Canadian state built after Confederation?",
    "learningOutcome": "Students examine the deliberate acts of state building.",
    "type": "Knowledge",
    "text": "The need and desire to grow the Dominion of Canada through expansion west was motivated by a broader strategy to strengthen the Canadian state by expanding territory, securing resources, and establishing national unity.",
