    "learningOutcome": "Students compare the role of individuals and governments in economic systems.",
    "type": "Knowledge",
    "text": "Economic systems attempt to address the issue of scarcity and make decisions about production, consumption, and distribution of goods and services by answering three basic economic questions:\n• What goods and services should be produced?\n• How should goods and services be produced?\n• For whom should goods and services be produced?",
