    "organizingIdeaDescription": "Evaluating processes and structures of organizations builds understanding of decision making in the world.",
    "guidingQuestion": "In what ways can society be organized?",
    "learningOutcome": "Students compare government control and individual rights within political systems.",
    "type": "Knowledge",
    "text": "Ridings and Constituencies Canada’s parliament contains the executive and legislative branches, which are represented by\n• the representative of the sovereign, the Governor General\n• the Prime Minister and Cabinet Ministers, who are elected Members of Parliament\n• the Senate, where senators are appointed on recommendation of the prime minister\n• the Members of Parliament who are elected by Canadians to the House of Commons",
    "curriculumFormat": "k6-standard",
    "bloomEligible": false,
    "assessmentTarget": false,
