    "learningOutcome": "Students compare government control and individual rights within political systems.",
    "type": "Knowledge",
    "text": "Government and political systems, as well as party systems, are organized differently based on opportunities for opposition and debate and are classified as,\n• a one-party system, as in China\n• a two-party system, as in the United States\n• a multiparty system, such as in Alberta, Canada and Europe.",
