    "guidingQuestion": "How did economic changes transform Canada into a modern economy?",
    "learningOutcome": "Students analyze how economic crisis, growth, and global trade shaped Canada’s modern economy.",
    "type": "Knowledge",
    "text": "The Great Depression was caused by several factors, including\n• overproduction of goods\n• declining consumer demand\n• the collapse of global trade\n• financial instability In response to the Great Depression, governments in Canada and the United States began to take a more active role in the economy such as public works, social welfare programs, and deficit spending.",
