    "learningOutcome": "Students analyze how economic crisis, growth, and global trade shaped Canada’s modern economy.",
    "type": "Knowledge",
    "text": "After World War II, Canada’s economy expanded and diversified, contributing to the development of a modern industrial economy. This included the growth of economic sectors including\n• automobile manufacturing\n• petroleum and energy production\n• papers and forestry\n• hydroelectric power development Canada’s population became increasingly urbanized after WWII, with more people living in cities rather than rural areas.",
