    "text": "Laws are created through a formal legislative process, including\n• bill drafting\n• first reading (introduction)\n• second reading (debate)\n• committee stage (detailed review)\n• third reading (final approval)\n• approval by the Senate\n• royal assent by the Crown A formal legislative process ensures that laws are debated, reviewed, and approved by multiple institutions before being enacted.",
