    "type": "Knowledge",
    "text": "The Canadian Charter of Rights and Freedoms (1982) protects fundamental rights such as\n• freedom of expression\n• equality\n• legal protections Canadian citizens have rights (e.g., voting, freedoms) and responsibilities, including\n• obeying laws\n• participating in democracy\n• respecting the rights of others",
    "curriculumFormat": "k6-standard",
    "bloomEligible": false,
    "assessmentTarget": false,
