    "text": "Changes in legislation extended individual rights that were once denied to people based on\n• age\n• race\n• gender\n• income\n• ethnic origin\n• religious or spiritual beliefs Individuals and groups have changed the social and political landscape in Canada through advocacy for changes in legislation, including advocacy for women’s suffrage by the Famous Five.",
