    "learningOutcome": "Students examine the impact of changing legislation on citizenship in Canada.",
    "type": "Knowledge",
    "text": "Legislation has been amended over time to reflect Canadian pluralism and immigration from non-European countries, such as India, China, the Philippines, and Vietnam, including\n• the ability to pass on citizenship from one generation to the next\n• inclusive point systems and designations, such as economic, family, refugee, and humanitarian classes In Canada, citizenship status can be designated as\n• citizen at birth or through naturalization\n• temporary resident with a study, work, or visitor permit\n• permanent resident\n• refugee Permanent residents and refugees in Canada are non-citizens with some of the same rights as citizens and some restrictions.",
