    "organizingIdeaDescription": "Understanding local, national, and global issues empowers individual and collective action toward an inclusive society.",
    "guidingQuestion": "In what ways do citizen rights evolve?",
    "learningOutcome": "Students examine the impact of changing legislation on citizenship in Canada.",
    "type": "Knowledge",
    "text": "multiculturalism and immigration, for example,\n• the Royal Commission of Bilingualism and Biculturalism (1963)\n• the Royal Commission on the Status of Women (1967)\n• the Official Languages Act (1969)\n• the Canadian Multiculturalism Policy (1971) Canada gained sovereign control over its constitution through gradual patriation, culminating in the Constitution Act (1982), which entrenched the Canadian Charter of Rights and Freedoms.",
    "curriculumFormat": "k6-standard",
    "bloomEligible": false,
    "assessmentTarget": false,
    "sourcePage": 12,
